package io.horizontalsystems.stellarkit

import org.junit.Assert.assertEquals
import org.junit.Test
import org.stellar.sdk.Network
import org.stellar.sdk.Transaction

class Protocol23XdrTest {

    // A Soroban transaction with SorobanTransactionData ext v1 (Protocol 23,
    // archived-entries extension) — an Axelar ITS interchain_transfer built by
    // uswap-server. stellar-sdk 1.0.0 (pinned by wallet-sdk 2.0.0) failed to parse
    // this with "Unknown enum value"; the forced 4.x SDK must handle it.
    @Test
    fun parsesSorobanDataExtV1Envelope() {
        val transaction = Transaction.fromEnvelopeXdr(P23_ENVELOPE, Network.PUBLIC) as Transaction

        assertEquals(1, transaction.operations.size)
        // Round-trip must be lossless — the same envelope is what gets signed and submitted.
        assertEquals(P23_ENVELOPE, transaction.toEnvelopeXdrBase64())
    }

    companion object {
        private const val P23_ENVELOPE = ""
    }
}
